/* Ensure hidden attribute overrides any display settings */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1c23;
  --card-bg: #292d3e;
  --text-main: #f0f2f5;
  --accent-car: #e06c75;
  --accent-bus: #e5c07b;
  --accent-bike: #98c379;
  --btn-neutral: #4f5666;
  --btn-shadow: #111317;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  image-rendering: pixelated;
}

.traffic-counter-app {
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.app-header {
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--accent-bus);
  text-shadow: 2px 2px 0px var(--btn-shadow);
}

.app-subtitle {
  font-size: 1rem;
  opacity: 0.85;
  margin-top: 4px;
}

.dashboard-card {
  background: var(--card-bg);
  border: 4px solid var(--text-main);
  box-shadow: 6px 6px 0px var(--btn-shadow);
  padding: 24px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.summary-panel {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-color);
  border: 3px solid var(--text-main);
  padding: 12px 16px;
}

.summary-label {
  font-weight: bold;
  letter-spacing: 1px;
  font-size: 1rem;
}

.summary-value {
  font-size: 1.75rem;
  font-weight: bold;
  color: var(--text-main);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.stat-box {
  background: var(--bg-color);
  border: 3px solid var(--text-main);
  padding: 12px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
}

.icon-wrapper {
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Pure CSS Pixel Art Icons */
.pixel-art {
  position: relative;
}

.pixel-car {
  width: 20px;
  height: 12px;
  background: var(--accent-car);
  box-shadow: -4px 4px 0 0 var(--accent-car), 4px 4px 0 0 var(--accent-car), -2px 12px 0 0 #000, 2px 12px 0 0 #000;
}

.pixel-bus {
  width: 24px;
  height: 16px;
  background: var(--accent-bus);
  box-shadow: -3px 16px 0 0 #000, 3px 16px 0 0 #000;
}

.pixel-bike {
  width: 16px;
  height: 10px;
  border: 2px solid var(--accent-bike);
  border-radius: 50%;
  box-shadow: 10px 0 0 -2px var(--accent-bike);
}

.type-title {
  font-size: 1rem;
  margin-top: 6px;
  letter-spacing: 1px;
}

.car-box .type-title { color: var(--accent-car); }
.bus-box .type-title { color: var(--accent-bus); }
.bike-box .type-title { color: var(--accent-bike); }

.count-text {
  font-size: 1.25rem;
  font-weight: bold;
}

.percent-text {
  font-size: 1rem;
  opacity: 0.9;
}

.progress-track {
  width: 100%;
  height: 8px;
  background: #111;
  border: 1px solid var(--text-main);
  margin-top: 4px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  transition: width 0.2s steps(4, end);
}

.car-box .progress-fill { background-color: var(--accent-car); }
.bus-box .progress-fill { background-color: var(--accent-bus); }
.bike-box .progress-fill { background-color: var(--accent-bike); }

.controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tally-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 8px;
  cursor: pointer;
  border: 3px solid var(--text-main);
  color: #1a1c23;
  box-shadow: 3px 3px 0px var(--btn-shadow);
  outline: none;
  user-select: none;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:hover:not(:disabled) {
  filter: brightness(1.1);
}

.pixel-btn:focus-visible {
  outline: 3px dashed #ffffff;
  outline-offset: 3px;
}

.pixel-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--btn-shadow);
}

.pixel-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.btn-car {
  background-color: var(--accent-car);
  color: #1a1c23;
}

.btn-bus {
  background-color: var(--accent-bus);
  color: #1a1c23;
}

.btn-bike {
  background-color: var(--accent-bike);
  color: #1a1c23;
}

.action-buttons {
  display: flex;
}

.btn-undo {
  width: 100%;
  background-color: var(--btn-neutral);
  color: #ffffff;
}

.status-log {
  font-size: 0.9rem;
  text-align: center;
  padding: 8px;
  background: var(--bg-color);
  border: 2px dashed var(--btn-neutral);
  color: var(--text-main);
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 440px) {
  .stats-grid {
    grid-template-columns: 1fr;
  }
  .tally-buttons {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const counts = {
    car: 0,
    bus: 0,
    bike: 0
  };

  const history = [];

  const domElements = {
    carCount: document.getElementById('car-count'),
    busCount: document.getElementById('bus-count'),
    bikeCount: document.getElementById('bike-count'),
    totalCount: document.getElementById('total-count'),
    carPercent: document.getElementById('car-percent'),
    busPercent: document.getElementById('bus-percent'),
    bikePercent: document.getElementById('bike-percent'),
    carBar: document.getElementById('car-bar'),
    busBar: document.getElementById('bus-bar'),
    bikeBar: document.getElementById('bike-bar'),
    btnCar: document.getElementById('btn-car'),
    btnBus: document.getElementById('btn-bus'),
    btnBike: document.getElementById('btn-bike'),
    btnUndo: document.getElementById('btn-undo'),
    statusLog: document.getElementById('status-log')
  };

  function calculatePercentages(total) {
    if (total === 0) {
      return { car: '0.0', bus: '0.0', bike: '0.0' };
    }
    return {
      car: ((counts.car / total) * 100).toFixed(1),
      bus: ((counts.bus / total) * 100).toFixed(1),
      bike: ((counts.bike / total) * 100).toFixed(1)
    };
  }

  function updateUI() {
    const total = counts.car + counts.bus + counts.bike;
    const percentages = calculatePercentages(total);

    domElements.carCount.textContent = counts.car;
    domElements.busCount.textContent = counts.bus;
    domElements.bikeCount.textContent = counts.bike;
    domElements.totalCount.textContent = total;

    domElements.carPercent.textContent = percentages.car;
    domElements.busPercent.textContent = percentages.bus;
    domElements.bikePercent.textContent = percentages.bike;

    domElements.carBar.style.width = `${percentages.car}%`;
    domElements.busBar.style.width = `${percentages.bus}%`;
    domElements.bikeBar.style.width = `${percentages.bike}%`;

    const canUndo = history.length > 0;
    domElements.btnUndo.disabled = !canUndo;
    domElements.btnUndo.setAttribute('aria-disabled', String(!canUndo));
  }

  function addVehicle(type) {
    if (!(type in counts)) return;
    counts[type] += 1;
    history.push(type);
    domElements.statusLog.textContent = `Added 1 ${type.toUpperCase()}.`;
    updateUI();
  }

  function undoLast() {
    if (history.length === 0) return;
    const lastType = history.pop();
    if (counts[lastType] > 0) {
      counts[lastType] -= 1;
    }
    domElements.statusLog.textContent = `Undid last entry (${lastType.toUpperCase()}).`;
    updateUI();
  }

  domElements.btnCar.addEventListener('click', () => addVehicle('car'));
  domElements.btnBus.addEventListener('click', () => addVehicle('bus'));
  domElements.btnBike.addEventListener('click', () => addVehicle('bike'));
  domElements.btnUndo.addEventListener('click', undoLast);

  updateUI();
});
